#!/usr/bin/env bash

# Run search on the original test split while using the data generated by
# generate_llava70b_dataset_text.py as the validation split.

set -euo pipefail

cd "$(dirname "$0")/.."

BASE_MODEL="${BASE_MODEL:-llava-hf-llava-v1.6-mistral-7b-hf}"
GPUS="${GPUS:-4}"
NUM_NODES="${NUM_NODES:-1}"
TARGET_TYPE="${TARGET_TYPE:-text}"
DATASET="${DATASET:-flickr}"
TASK_TYPE="${TASK_TYPE:-ir}"
FILTER="${FILTER:-no_filter}"
EXPENDED_TOKENS="${EXPENDED_TOKENS:-0}"
MANUAL="${MANUAL:-no_manual}"
MANUAL_LENGTH="${MANUAL_LENGTH:-40}"
CLUSTER="${CLUSTER:-no_cluster}"
REPS_LOC="${REPS_LOC:-after_pad}"
EOL_TYPE="${EOL_TYPE:-disassembleeol_separate}"
SPARSE_VALUE_TYPE="${SPARSE_VALUE_TYPE:-sum}"
SPARSE_LOWER_OR_UPPER="${SPARSE_LOWER_OR_UPPER:-lower}"
CALCULATE_TYPE="${CALCULATE_TYPE:-concat}"
PROMPT_TYPE="${PROMPT_TYPE:-prompt_5}"
USE_MEAN="${USE_MEAN:-no_mean}"
ALPHA="${ALPHA:-0.9}"
BETA="${BETA:-0.1}"
USE_FIXED_ALPHA="${USE_FIXED_ALPHA:-false}"
GENERATED_VALIDATION_DATA_ROOT="${GENERATED_VALIDATION_DATA_ROOT:-./generated_llava70b_data}"

# This script always enables generated validation data.  The test split is
# still selected explicitly below and is not replaced by the generated files.
GENERATED_VALIDATION_ARGS=(
    --use_generated_validation_data
    --generated_validation_data_root "${GENERATED_VALIDATION_DATA_ROOT}"
)

FUSION_ALPHA_ARGS=()
if [[ "${USE_FIXED_ALPHA}" == "true" ]]; then
    FUSION_ALPHA_ARGS+=(--use_fixed_alpha)
fi

MODEL_PATH="./checkpoints/${BASE_MODEL}"
COMMON_PATH="${BASE_MODEL}/${DATASET}/${TARGET_TYPE}/${FILTER}/${CALCULATE_TYPE}/${PROMPT_TYPE}"
PATH_SUFFIX="${EXPENDED_TOKENS}_${MANUAL}_${MANUAL_LENGTH}_${SPARSE_VALUE_TYPE}_${CLUSTER}_${REPS_LOC}_${EOL_TYPE}_${SPARSE_LOWER_OR_UPPER}_${USE_MEAN}"
TEST_REPS_PATH="${COMMON_PATH}/test/${PATH_SUFFIX}"
VAL_REPS_PATH="${COMMON_PATH}/val/${PATH_SUFFIX}_generated_val"
OUTPUT_PATH="${COMMON_PATH}/test/${PATH_SUFFIX}/result"

deepspeed --num_gpus="${GPUS}" --num_nodes="${NUM_NODES}" src/search.py \
    --model_name_or_path "${MODEL_PATH}" \
    --per_device_batch_size "${PER_DEVICE_BATCH_SIZE:-1}" \
    --threads "${THREADS:-16}" \
    --dataset_name "${DATASET}" \
    --task_type "${TASK_TYPE}" \
    --dataset_split test \
    --fp16 \
    --passage_reps "dense_output/${TEST_REPS_PATH}" \
    --sparse_index "sparse_output/${TEST_REPS_PATH}" \
    --val_passage_reps "dense_output/${VAL_REPS_PATH}" \
    --val_sparse_index "sparse_output/${VAL_REPS_PATH}" \
    --output_dir "./output/${OUTPUT_PATH}" \
    --depth "${DEPTH:-1000}" \
    --remove_query \
    --query_type "${QUERY_TYPE:-image}" \
    --use_gpu \
    --retrieval_batch_size "${RETRIEVAL_BATCH_SIZE:-1}" \
    --num_expended_tokens "${EXPENDED_TOKENS}" \
    --alpha "${ALPHA}" \
    --beta "${BETA}" \
    "${FUSION_ALPHA_ARGS[@]}" \
    --reps_loc "${REPS_LOC}" \
    --eol_type "${EOL_TYPE}" \
    --sparse_value_type "${SPARSE_VALUE_TYPE}" \
    --sparse_lower_or_upper "${SPARSE_LOWER_OR_UPPER}" \
    --sparse_length "${SPARSE_LENGTH:-40}" \
    --calculate_type "${CALCULATE_TYPE}" \
    --prompt_type "${PROMPT_TYPE}" \
    "${GENERATED_VALIDATION_ARGS[@]}"
